using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using TabulariusAI.Web.Data;using TabulariusAI.Web.Data.Entities;using TabulariusAI.Web.Data.Identity;using TabulariusAI.Web.Models;using TabulariusAI.Web.Services.AI;
namespace TabulariusAI.Web.Controllers;
[Authorize(Roles=ApplicationRoles.Administrator)]public sealed class AiSettingsController(TabulariusDbContext dbContext,IEnumerable<IAiProvider> providers,ILogger<AiSettingsController> logger):Controller
{
[HttpGet]public async Task<IActionResult> Index(CancellationToken cancellationToken){var s=await dbContext.AiSettings.AsNoTracking().SingleOrDefaultAsync(cancellationToken)??new AiSettings();return View(new AiSettingsViewModel{IsEnabled=s.IsEnabled,Provider=s.Provider,Endpoint=s.Endpoint,Model=s.Model,Temperature=s.Temperature,TimeoutSeconds=s.TimeoutSeconds,SystemPrompt=s.SystemPrompt,HomePrompt=s.HomePrompt,HomeCacheMinutes=s.HomeCacheMinutes,AnalyticsOverviewPrompt=s.AnalyticsOverviewPrompt,AnomaliesPrompt=s.AnomaliesPrompt,AccountAnalysisPrompt=s.AccountAnalysisPrompt,VatAnalysisPrompt=s.VatAnalysisPrompt,TrialBalancePrompt=s.TrialBalancePrompt,IncomeStatementPrompt=s.IncomeStatementPrompt,BalanceSheetPrompt=s.BalanceSheetPrompt,HasApiKey=!string.IsNullOrWhiteSpace(s.ApiKey)});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Index(AiSettingsViewModel m,CancellationToken ct){if(m.Provider is not("Ollama" or "Mistral"))ModelState.AddModelError(nameof(m.Provider),"Selecione Ollama ou Mistral.");if(!ModelState.IsValid)return View(m);var s=await dbContext.AiSettings.SingleOrDefaultAsync(ct);if(s is null){s=new AiSettings();dbContext.AiSettings.Add(s);}s.IsEnabled=m.IsEnabled;s.Provider=m.Provider;s.Endpoint=m.Endpoint.Trim();s.Model=m.Model.Trim();s.Temperature=m.Temperature;s.TimeoutSeconds=m.TimeoutSeconds;s.SystemPrompt=m.SystemPrompt.Trim();s.HomePrompt=m.HomePrompt.Trim();s.HomeCacheMinutes=m.HomeCacheMinutes;s.AnalyticsOverviewPrompt=m.AnalyticsOverviewPrompt.Trim();s.AnomaliesPrompt=m.AnomaliesPrompt.Trim();s.AccountAnalysisPrompt=m.AccountAnalysisPrompt.Trim();s.VatAnalysisPrompt=m.VatAnalysisPrompt.Trim();s.TrialBalancePrompt=m.TrialBalancePrompt.Trim();s.IncomeStatementPrompt=m.IncomeStatementPrompt.Trim();s.BalanceSheetPrompt=m.BalanceSheetPrompt.Trim();if(!string.IsNullOrWhiteSpace(m.ApiKey))s.ApiKey=m.ApiKey.Trim();s.UpdatedAtUtc=DateTime.UtcNow;await dbContext.SaveChangesAsync(ct);TempData["AiSettingsSaved"]="Definições de inteligência artificial guardadas.";return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> TestConnection(CancellationToken cancellationToken){var settings=await dbContext.AiSettings.AsNoTracking().SingleOrDefaultAsync(cancellationToken);if(settings is null){TempData["AiSettingsError"]="Guarde primeiro as definições do modelo.";return RedirectToAction(nameof(Index));}var provider=providers.SingleOrDefault(item=>string.Equals(item.Name,settings.Provider,StringComparison.OrdinalIgnoreCase));if(provider is null){TempData["AiSettingsError"]=$"O fornecedor '{settings.Provider}' não é suportado.";return RedirectToAction(nameof(Index));}if(string.Equals(settings.Provider,"Mistral",StringComparison.OrdinalIgnoreCase)&&string.IsNullOrWhiteSpace(settings.ApiKey)){TempData["AiSettingsError"]="Configure a API key da Mistral antes de testar a ligação.";return RedirectToAction(nameof(Index));}try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(Math.Clamp(settings.TimeoutSeconds,10,600)));using var linked=CancellationTokenSource.CreateLinkedTokenSource(cancellationToken,timeout.Token);var tool=new AiToolDefinition("tabularius_compatibility_check","Tool de diagnóstico usada para confirmar que o modelo suporta tool calling.",new{type="object",properties=new{},required=Array.Empty<string>(),additionalProperties=false});var result=await provider.CompleteAsync(settings.Endpoint,settings.Model,settings.ApiKey,0,"Estás a executar um teste técnico de compatibilidade. Tens de chamar obrigatoriamente a tool tabularius_compatibility_check. Não respondas diretamente ao utilizador.",[new AiMessage("user","Chama agora a tool tabularius_compatibility_check para validar a compatibilidade com o Tabularius AI.")],[tool],linked.Token);if(!result.ToolCalls.Any(call=>string.Equals(call.Name,"tabularius_compatibility_check",StringComparison.Ordinal))){TempData["AiSettingsError"]=$"O modelo {settings.Model} responde através de {settings.Provider}, mas não confirmou suporte a tool calling.";return RedirectToAction(nameof(Index));}TempData["AiSettingsTest"]=$"Compatibilidade confirmada · {settings.Provider} · {settings.Model} · tool calling disponível";}catch(Exception ex) when(ex is HttpRequestException or InvalidOperationException or TaskCanceledException){logger.LogWarning(ex,"AI compatibility test failed for provider {Provider} and model {Model}.",settings.Provider,settings.Model);TempData["AiSettingsError"]=$"Não foi possível confirmar a compatibilidade de {settings.Provider} com o modelo {settings.Model}.";}return RedirectToAction(nameof(Index));}}
